        private static readonly Dictionary<string, BitmapImage?> Cache = new(StringComparer.Ordinal);
        public static BitmapImage? Get(string key)
        {
            if (Cache.TryGetValue(key, out var cached)) return cached;
            if (!Payloads.TryGetValue(key, out var payload)) return null;
            try
            {
                byte[] bytes = Convert.FromBase64String(payload);
                using var stream = new MemoryStream(bytes, writable: false);
                var image = new BitmapImage(); image.BeginInit();
                image.CacheOption = BitmapCacheOption.OnLoad; image.StreamSource = stream; image.EndInit(); image.Freeze();
                Cache[key] = image; return image;
            }
            catch (Exception) { Cache[key] = null; return null; }
        }
